#define PTO_MX_OPT_ACC_SA_0(S,O,I) PTO_MX_OPT_ACC_SA(0,S,O,I)
#define PTO_MX_OPT_ACC_SA_1(S,O,I) PTO_MX_OPT_ACC_SA(1,S,O,I)
